import React, { ReactHTML } from 'react';
import { MatrixEvent } from "matrix-js-sdk/src/models/event";
import { MsgType } from "matrix-js-sdk/src/@types/event";

import MatrixClientContext from "../../../contexts/MatrixClientContext";
import DisambiguatedProfile from "./DisambiguatedProfile";
import RoomContext, { TimelineRenderingType } from '../../../contexts/RoomContext';
import SettingsStore from "../../../settings/SettingsStore";
import { MatrixClientPeg } from "../../../MatrixClientPeg";

interface IProps {
    mxEvent: MatrixEvent;
    onClick?(): void;
    as?: keyof ReactHTML;
    showForEmote?: boolean;
}

export default class SenderProfile extends React.PureComponent<IProps> {
    public static contextType = MatrixClientContext;
    public context!: React.ContextType<typeof MatrixClientContext>;

    render() {
        const { mxEvent, onClick, as, showForEmote } = this.props;
        const msgtype = mxEvent.getContent().msgtype;

        let member = mxEvent.sender;
        if (SettingsStore.getValue("feature_use_only_current_profiles")) {
            const room = MatrixClientPeg.get().getRoom(mxEvent.getRoomId());
            if (room) {
                member = room.getMember(mxEvent.getSender());
            }
        }

        return <RoomContext.Consumer>
            { roomContext => {
                if (!showForEmote && msgtype === MsgType.Emote &&
                    roomContext.timelineRenderingType !== TimelineRenderingType.ThreadsList
                ) {
                    return null; // emote message must include the name so don't duplicate it
                }

                return (
                    <DisambiguatedProfile
                        as={as}
                        fallbackName={mxEvent.getSender() || ""}
                        onClick={onClick}
                        member={member}
                        colored={true}
                        emphasizeDisplayName={true}

        const displayNameClasses = classNames({
            "mx_DisambiguatedProfile_displayName": emphasizeDisplayName,
            [colorClass]: true,
        });

        return React.createElement(as, {
            className: "mx_DisambiguatedProfile",
            onClick,
        },
        <span className={displayNameClasses} dir="auto">
            { rawDisplayName }
        </span>,
        mxidElement);
    }
}

